def sign(p1, p2, p3):
    return (p1[0] - p3[0]) * (p2[1] - p3[1]) - (p2[0] - p3[0]) * (p1[1] - p3[1])

def area_of_polygon(vertices: List[List[int]]) -> float:
    n = len(vertices)
    area = 0.0
    for i in range(n):
        j = (i + 1) % n
        area += sign(vertices[i], vertices[j], (0, 0))
    return abs(area) / 2.0

def get_prefix_areas(vertices: List[List[int]]) -> List[float]:
    n = len(vertices)
    prefix_areas = [0.0]
    current_area = 0.0
    for i in range(1, n):
        current_area += sign(vertices[i-1], vertices[i], (0, 0))
        prefix_areas.append(abs(current_area) / 2.0)
    return prefix_areas

def find_bulkhead_positions(C: int, N: int, vertices: List[List[int]]) -> List[float]:
    prefix_areas = get_prefix_areas(vertices)
