            j = (i + 1) % len(vertices)
            if vertices[i][0] <= x < vertices[j][0]:
                below_x += sign((x, 0), vertices[i], vertices[j])
            elif vertices[j][0] <= x < vertices[i][0]:
                above_x += sign((x, 0), vertices[j], vertices[i])
        return abs(below_x) / 2.0 + abs(above_x) / 2.0

